// Block (composition) — a horizontally scrollable feature-by-plan comparison.
// Table owns tabular behavior, ScrollArea owns overflow, Badge owns plan labels, and Stack arranges the section.
import type { ReactNode, Ref } from "react";
import { ScrollArea } from "../components/ScrollArea";
import { Badge } from "../components/Badge";
import { Stack } from "../layouts/Stack";
import {
  Table,
  TableBody,
  TableCell,
  TableColumn,
  TableHeader,
  TableRow,
} from "../components/Table";
import "./ComparisonTable.css";

export interface ComparisonTableProps {
  features: string[];
  plans: {
    name: string;
    values: (boolean | string)[];
  }[];
  className?: string;
  ref?: Ref<HTMLElement>;
}

type ComparisonColumn = {
  id: string;
  label: ReactNode;
};

type ComparisonRow = {
  id: string;
  feature: string;
  [key: string]: boolean | string;
};

function formatValue(value: boolean | string) {
  if (typeof value === "boolean") return value ? "✓" : "—";
  return value;
}

export function ComparisonTable({
  features,
  plans,
  className,
  ref,
}: ComparisonTableProps) {
  const columns: ComparisonColumn[] = [
    { id: "feature", label: "Feature" },
    ...plans.map((plan, index) => ({
      id: `plan-${index}`,
      label: <Badge variant="neutral">{plan.name}</Badge>,
    })),
  ];

  const rows: ComparisonRow[] = features.map((feature, featureIndex) => {
    const row: ComparisonRow = { id: `feature-${featureIndex}`, feature };
    plans.forEach((plan, planIndex) => {
      row[`plan-${planIndex}`] = plan.values[featureIndex] ?? "—";
    });
    return row;
  });

  return (
    <Stack
      as="section"
      ref={ref}
      gap="none"
      aria-label="Plan comparison"
      className={className ? `sd-comparisontable ${className}` : "sd-comparisontable"}
    >
      {/* The Block root used to carry `overflow-x: auto` directly, which made it a scroll region
          with no way to reach it from a keyboard (axe scrollable-region-focusable / WCAG 2.1.1).
          ScrollArea is the same container plus the tab stop, gated on real overflow. */}
      <ScrollArea orientation="horizontal" className="sd-comparisontable__scroll">
        <Table aria-label="Feature comparison by plan">
          <TableHeader columns={columns}>
            {(column) => (
              <TableColumn id={column.id} isRowHeader={column.id === "feature"}>
                {column.label}
              </TableColumn>
            )}
          </TableHeader>
          <TableBody items={rows}>
            {(row) => (
              <TableRow id={row.id} columns={columns}>
                {(column) => <TableCell>{formatValue(row[column.id])}</TableCell>}
              </TableRow>
            )}
          </TableBody>
        </Table>
      </ScrollArea>
    </Stack>
  );
}

.sd-comparisontable {
  width: 100%;
}

/* The scrollport, not the root. `overflow-x` lived on the root and gave it scrolling without
   focusability; ScrollArea owns the overflow now, and this only has to let it be NARROWER than the
   table it holds (a flex/grid item defaults to `min-width: auto` and would grow to min-content). */
.sd-comparisontable__scroll {
  min-width: 0;
  width: 100%;
}
